package com.neuroflow.studysession.entity;
import com.neuroflow.subject.entity.Subject;import com.neuroflow.user.entity.User;import jakarta.persistence.*;import java.time.*;import java.util.UUID;import lombok.Getter;import lombok.Setter;
@Getter @Setter @Entity @Table(name="study_sessions", indexes={@Index(name="idx_study_sessions_user_date", columnList="user_id,session_date"),@Index(name="idx_study_sessions_subject", columnList="subject_id")})
public class StudySession { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="subject_id") private Subject subject; @Column(name="session_date",nullable=false) private LocalDate sessionDate; @Column(name="start_time") private Instant startTime; @Column(name="end_time") private Instant endTime; @Column(name="duration_minutes",nullable=false) private Integer durationMinutes; @Column(name="study_type",nullable=false,length=40) private String studyType; @Column(name="focus_level") private Short focusLevel; @Column(columnDefinition="text") private String notes; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; }
